import os
from dataclasses import dataclass, field

TRUE = {"1", "true", "yes", "on"}

@dataclass(frozen=True)
class Settings:
    # repr=False keeps it out of logs
    database_url: str = field(repr=False)
    debug: bool = False
    workers: int = 4

def load_settings(env=os.environ):
    if "DATABASE_URL" not in env:
        # fail fast, with a clear message
        raise SystemExit("no DATABASE_URL")
    debug = env.get("DEBUG", "").lower()
    return Settings(
        database_url=env["DATABASE_URL"],
        debug=debug in TRUE,
        workers=int(env.get("WORKERS", 4)),
    )

env = {"DATABASE_URL": "postgres://db/app",
       "DEBUG": "false"}
print(load_settings(env))
print(bool("false"))   # True!
# Settings(debug=False, workers=4)
# True

